import type { JobRow } from './db.ts';

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MAX_INPUT_LENGTH = 1000;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;

export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isIntegerIn = (v: unknown, min: number, max: number): v is number =>
  typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;

/** Validates a parsed POST /api/jobs body, applying defaults. Reports every offending field. */
export function validateSubmission(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const obj = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const raw = obj.input;
  if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string' });
  } else if (raw.length < 1 || raw.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = raw;
  }

  const steps = obj.steps === undefined ? DEFAULT_STEPS : obj.steps;
  if (!isIntegerIn(steps, 1, MAX_STEPS)) {
    fields.push({ field: 'steps', message: `steps must be an integer from 1 to ${MAX_STEPS}` });
  }

  const failAttempts = obj.failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : obj.failAttempts;
  if (!isIntegerIn(failAttempts, 0, MAX_FAIL_ATTEMPTS)) {
    fields.push({ field: 'failAttempts', message: `failAttempts must be an integer from 0 to ${MAX_FAIL_ATTEMPTS}` });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps: steps as number, failAttempts: failAttempts as number } };
}

/** Maps a stored row to the public job representation. */
export function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

