import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, type JobRow } from './db.ts';
import { toJob, validateSubmission, type FieldError, type Submission } from './jobs.ts';

/** The worker writes a heartbeat about once a second; older than this means it is down. */
const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
);
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAllNewestFirst = db.prepare('SELECT * FROM jobs ORDER BY rowid DESC');
const selectHeartbeat = db.prepare('SELECT beat_ms FROM worker_heartbeat WHERE id = 1');

type CreateOutcome =
  | { kind: 'created'; row: JobRow }
  | { kind: 'replayed'; row: JobRow }
  | { kind: 'conflict' };

/** Creates a job, or resolves an Idempotency-Key replay, inside one immediate transaction. */
function createJob(submission: Submission, key: string | undefined): CreateOutcome {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        const same =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    insertJob.run(id, submission.input, submission.steps, submission.failAttempts, key ?? null, now, now);
    const row = selectById.get(id) as JobRow;
    db.exec('COMMIT');
    return { kind: 'created', row };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open
    }
    throw e;
  }
}

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];

  let key: string | undefined;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_PATTERN.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let submission: Submission | undefined;
  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsedOk = false;
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsedOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else fields.push(...result.fields);
    }
  }

  if (fields.length > 0 || submission === undefined) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }

  const outcome = createJob(submission, key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function handleHealth(res: ServerResponse): void {
  const hb = selectHeartbeat.get() as { beat_ms: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.beat_ms <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/') {
    if (!isGet) return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (!isGet) return methodNotAllowed(res, ['GET']);
    return handleHealth(res);
  }

  if (pathname === '/api/jobs') {
    if (isGet) {
      const jobs = (selectAllNewestFirst.all() as unknown as JobRow[]).map(toJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (!isGet) return methodNotAllowed(res, ['GET']);
    let id = match[1]!;
    try {
      id = decodeURIComponent(id);
    } catch {
      // leave the raw segment; it will simply not match
    }
    const row = selectById.get(id) as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  setTimeout(() => process.exit(0), 3_000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

